class Solution {
public:
    vector<int> stringIndices(vector<string>& wordsContainer, vector<string>& wordsQuery) {
        struct Node {
            int children[26];
            int bestIdx;
            int bestLen;
            Node() : bestIdx(-1), bestLen(-1) {
                for (int i = 0; i < 26; i++) children[i] = -1;
            }
        };
        vector<Node> trie;
        trie.reserve(500001);
        trie.emplace_back();

        for (int i = 0; i < (int)wordsContainer.size(); i++) {
            const string& w = wordsContainer[i];
            int len = (int)w.size();
            int node = 0;
            if (trie[node].bestIdx == -1 || len < trie[node].bestLen) {
                trie[node].bestIdx = i;
                trie[node].bestLen = len;
            }
            for (int j = len - 1; j >= 0; j--) {
                int c = w[j] - 'a';
                if (trie[node].children[c] == -1) {
                    trie[node].children[c] = (int)trie.size();
                    trie.emplace_back();
                }
                node = trie[node].children[c];
                if (trie[node].bestIdx == -1 || len < trie[node].bestLen) {
                    trie[node].bestIdx = i;
                    trie[node].bestLen = len;
                }
            }
        }

        vector<int> ans;
        ans.reserve(wordsQuery.size());
        for (const string& q : wordsQuery) {
            int node = 0;
            for (int j = (int)q.size() - 1; j >= 0; j--) {
                int c = q[j] - 'a';
                if (trie[node].children[c] == -1) break;
                node = trie[node].children[c];
            }
            ans.push_back(trie[node].bestIdx);
        }
        return ans;
    }
};
